/bin/bash -lc "cat > ~/code/benchmark/okf-local/main/source/work/g3_checkout_request/source/codex/1/src/util/checkoutRequest.mjs <<'EOF'
/**
 * Builds the checkout request the storefront POSTs to the backend.
 *
 * Field names follow the backend's v1 order request class
 * (PersistableAnonymousOrder / PersistableOrder / PersistablePayment):
 *  - quoteId       : chosen shipping option
 *  - currency      : order currency
 *  - termsAccepted : whether the terms were accepted
 *  - orderNote     : order comment
 *  - payment.processor   : payment module
 *  - payment.cardToken   : payment token
 *  - payment.amount      : amount
 */
export function buildCheckoutRequest({
  cartCode,
  shippingOptionId,
  currency,
  paymentToken,
  paymentModule,
  amount,
  agreedToTerms,
  comments,
}) {
  return {
    method: 'POST',
    path: "'`cart/${cartCode}/checkout`,
    body: {
      quoteId: shippingOptionId,
      currency,
      termsAccepted: agreedToTerms,
      orderNote: comments,
      payment: {
        paymentType: '"'CREDITCARD',
        transactionType: 'CAPTURE',
        processor: paymentModule,
        cardToken: paymentToken,
        amount,
      },
    },
  };
}
EOF
